-- 超大倍率鉴定卷轴：15个数量单位 × 13档倍率，共195张。
-- 物品ID范围：999200-999394；全部绑定鉴定组1。
-- 基础模板使用原版附魔卷轴38679的外观，并用无限制物品目标法术47147显示目标光标。

CREATE TABLE IF NOT EXISTS `_物品鉴定_卷轴配置` (
  `卷轴物品ID` INT UNSIGNED NOT NULL COMMENT 'item_template.entry；表中存在记录即启用',
  `卷轴类型` TINYINT UNSIGNED NOT NULL COMMENT '1=鉴定倍率卷轴，2=清理卷轴',
  `倍率` DECIMAL(65,0) UNSIGNED NOT NULL DEFAULT 0 COMMENT '鉴定倍率卷轴覆盖写入的倍率；清理卷轴填0',
  `鉴定组ID` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '鉴定倍率卷轴绑定的鉴定组；清理卷轴填0',
  PRIMARY KEY (`卷轴物品ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='物品鉴定系统卷轴配置';

DROP TEMPORARY TABLE IF EXISTS `_tmp_物品鉴定_超大倍率卷轴映射`;
CREATE TEMPORARY TABLE `_tmp_物品鉴定_超大倍率卷轴映射` (
  `卷轴物品ID` INT UNSIGNED NOT NULL,
  `显示倍率` VARCHAR(32) NOT NULL,
  `倍率` DECIMAL(65,0) UNSIGNED NOT NULL,
  PRIMARY KEY (`卷轴物品ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 万（10^4），物品ID 999200-999212

-- 亿（10^8），物品ID 999213-999225

-- 兆（10^12），物品ID 999226-999238

-- 京（10^16），物品ID 999239-999251

-- 垓（10^20），物品ID 999252-999264

-- 秭（10^24），物品ID 999265-999277

-- 穰（10^28），物品ID 999278-999290

-- 沟（10^32），物品ID 999291-999303

-- 涧（10^36），物品ID 999304-999316

-- 正（10^40），物品ID 999317-999329

-- 载（10^44），物品ID 999330-999342

-- 极（10^48），物品ID 999343-999355

-- 恒河沙（10^52），物品ID 999356-999368

-- 阿僧祇（10^56），物品ID 999369-999381

-- 那由他（10^60），物品ID 999382-999394

DROP TEMPORARY TABLE IF EXISTS `_tmp_物品鉴定_超大倍率卷轴模板`;
CREATE TEMPORARY TABLE `_tmp_物品鉴定_超大倍率卷轴模板` LIKE `item_template`;
ALTER TABLE `_tmp_物品鉴定_超大倍率卷轴模板` DROP PRIMARY KEY;
ALTER TABLE `_tmp_物品鉴定_超大倍率卷轴模板`
  ADD COLUMN `_新卷轴物品ID` INT UNSIGNED NOT NULL;

SELECT `基础模板`.*, `映射`.`卷轴物品ID`
FROM `item_template` AS `基础模板`
CROSS JOIN `_tmp_物品鉴定_超大倍率卷轴映射` AS `映射`
WHERE `基础模板`.`entry` = 38679;

UPDATE `_tmp_物品鉴定_超大倍率卷轴模板` AS `卷轴`
INNER JOIN `_tmp_物品鉴定_超大倍率卷轴映射` AS `映射`
  ON `映射`.`卷轴物品ID` = `卷轴`.`_新卷轴物品ID`
SET
  `卷轴`.`entry` = `映射`.`卷轴物品ID`,
  `卷轴`.`name` = CONCAT('鉴定卷轴·', `映射`.`显示倍率`),
  `卷轴`.`Quality` = 5,
  `卷轴`.`displayid` = 811,
  `卷轴`.`BuyPrice` = 0,
  `卷轴`.`SellPrice` = 0,
  `卷轴`.`bonding` = 0,
  `卷轴`.`description` = CONCAT(
    '对一件武器或护甲使用。未鉴定装备按鉴定组1进行鉴定；已有鉴定结果保持不变；最终倍率覆盖为',
    `映射`.`显示倍率`,
    '。'
  ),
  `卷轴`.`spellid_1` = 47147,
  `卷轴`.`spelltrigger_1` = 0,
  `卷轴`.`spellcharges_1` = 0,
  `卷轴`.`spellcooldown_1` = 0,
  `卷轴`.`spellcategory_1` = 0,
  `卷轴`.`spellcategorycooldown_1` = 0,
  `卷轴`.`ScriptName` = '',
  `卷轴`.`VerifiedBuild` = 12340;

ALTER TABLE `_tmp_物品鉴定_超大倍率卷轴模板` DROP COLUMN `_新卷轴物品ID`;

SELECT * FROM `_tmp_物品鉴定_超大倍率卷轴模板`;

SELECT `卷轴物品ID`, 1, `倍率`, 1
FROM `_tmp_物品鉴定_超大倍率卷轴映射`
ON DUPLICATE KEY UPDATE
  `卷轴类型` = VALUES(`卷轴类型`),
  `倍率` = VALUES(`倍率`),
  `鉴定组ID` = VALUES(`鉴定组ID`);

DROP TEMPORARY TABLE IF EXISTS `_tmp_物品鉴定_超大倍率卷轴模板`;
DROP TEMPORARY TABLE IF EXISTS `_tmp_物品鉴定_超大倍率卷轴映射`;
